syntax = "proto3";

package temporal.api.cloud.billing.v1;

option go_package = "go.temporal.io/api/cloud/billing/v1;billing";
option java_package = "io.temporal.api.cloud.billing.v1";
option java_multiple_files = true;
option java_outer_classname = "MessageProto";
option ruby_package = "Temporalio::Api::Cloud::Billing::V1";
option csharp_namespace = "Temporalio.Api.Cloud.Billing.V1";

import "google/protobuf/duration.proto";
import "google/protobuf/timestamp.proto";

message BillingReportSpec {
  // The start time of the billing report (in UTC).
  google.protobuf.Timestamp start_time_inclusive = 1;
  // The end time of the billing report (in UTC).
  google.protobuf.Timestamp end_time_exclusive = 2;
  // The duration after which the download url will expire.
  // Optional, default is 5 minutes and maximum is 1 hour.
  google.protobuf.Duration download_url_expiration_duration = 3;
  // The description for the billing report.
  // Optional, default is empty.
  string description = 4;
  // The data granularity of the billing report.
  // Optional, default is hourly.
  // temporal:versioning:min_version=v0.16.0
  BillingReportGranularity granularity = 5;

  enum BillingReportGranularity {
    BILLING_REPORT_GRANULARITY_UNSPECIFIED = 0;
    BILLING_REPORT_GRANULARITY_HOURLY = 1;
    BILLING_REPORT_GRANULARITY_DAILY = 2;
    BILLING_REPORT_GRANULARITY_MONTHLY = 3;
  }
}

message BillingReport {
  // The id of the billing report.
  string id = 1;
  // The current state of the billing report.
  BillingReportState state = 2;
  // The spec used to generate this billing report.
  BillingReportSpec spec = 3;
  // The download information for the billing report.
  // For future-proofness this is repeated as we may return multiple files (e.g. csv+meta/json, split by size/date, etc.)
  repeated Download download_info = 4;
  // The date and time when the billing report was requested.
  google.protobuf.Timestamp requested_time = 5;
  // The date and time when the billing report generation completed.
  google.protobuf.Timestamp generated_time = 6;
  // The async operation id associated with the billing report generation.
  string async_operation_id = 7;

  message Download {
    // The download url.
    string url = 1;
    // The time when the download url will expire.
    google.protobuf.Timestamp url_expiration_time = 2;
    // The file format of the billing report
    FileFormat file_format = 3;
    // The size of the file in bytes. Useful for pre-allocating space, progress indicators, etc.
    int64 file_size_bytes = 4;

    enum FileFormat {
      FILE_FORMAT_UNSPECIFIED = 0;
      FILE_FORMAT_CSV = 1;
    }
  }

  enum BillingReportState {
    BILLING_REPORT_STATE_UNSPECIFIED = 0;
    BILLING_REPORT_STATE_IN_PROGRESS = 1;
    BILLING_REPORT_STATE_GENERATED = 2;
    BILLING_REPORT_STATE_FAILED = 3;
  }
}

syntax = "proto3";

package temporal.api.cloud.usage.v1;

option go_package = "go.temporal.io/api/cloud/usage/v1;usage";
option java_package = "io.temporal.api.cloud.usage.v1";
option java_multiple_files = true;
option java_outer_classname = "MessageProto";
option ruby_package = "Temporalio::Api::Cloud::Usage::V1";
option csharp_namespace = "Temporalio.Api.Cloud.Usage.V1";

import "google/protobuf/timestamp.proto";

message Summary {
    // Start of UTC day for now (inclusive)
    google.protobuf.Timestamp start_time = 1;
    // End of UTC day for now (exclusive)
    google.protobuf.Timestamp end_time = 2;
    // Records grouped by namespace
    repeated RecordGroup record_groups = 3;
    // True if data for given time window is not fully available yet (e.g. delays)
    // When true, records for the given time range could still be added/updated in the future (until false) 
    bool incomplete = 4;
}

message RecordGroup {
    // GroupBy keys and their values for this record group. Multiple fields are combined with logical AND.
    repeated GroupBy group_bys = 1;
    repeated Record records = 2;
}

message GroupBy {
    GroupByKey key = 1;
    string value = 2;
}

message Record {
    RecordType type = 1;
    RecordUnit unit = 2;
    double value = 3;
}

enum RecordType {
    RECORD_TYPE_UNSPECIFIED = 0;
    RECORD_TYPE_ACTIONS = 1;
    RECORD_TYPE_ACTIVE_STORAGE = 2;
    RECORD_TYPE_RETAINED_STORAGE = 3;
}

enum RecordUnit {
    RECORD_UNIT_UNSPECIFIED = 0;
    RECORD_UNIT_NUMBER = 1;
    RECORD_UNIT_BYTE_SECONDS = 2;
}

enum GroupByKey {
    GROUP_BY_KEY_UNSPECIFIED = 0;
    GROUP_BY_KEY_NAMESPACE = 1;
}

syntax = "proto3";

package temporal.api.cloud.region.v1;

option go_package = "go.temporal.io/api/cloud/region/v1;region";
option java_package = "io.temporal.api.cloud.region.v1";
option java_multiple_files = true;
option java_outer_classname = "MessageProto";
option ruby_package = "Temporalio::Api::Cloud::Region::V1";
option csharp_namespace = "Temporalio.Api.Cloud.Region.V1";

message Region {
    // The id of the temporal cloud region.
    string id = 1;
    // The name of the cloud provider that's hosting the region.
    // Currently only "aws" is supported.
    // Deprecated: Not supported after v0.3.0 api version. Use cloud_provider instead. 
    // temporal:versioning:max_version=v0.3.0
    string cloud_provider_deprecated = 2 [deprecated = true];
    // The cloud provider that's hosting the region.
    // temporal:versioning:min_version=v0.3.0
    // temporal:enums:replaces=cloud_provider_deprecated
    CloudProvider cloud_provider = 5;
    // The region identifier as defined by the cloud provider.
    string cloud_provider_region = 3;
    // The human readable location of the region.
    string location = 4;

    // The cloud provider that's hosting the region.
    enum CloudProvider {
        CLOUD_PROVIDER_UNSPECIFIED = 0;
        CLOUD_PROVIDER_AWS = 1;
	    CLOUD_PROVIDER_GCP = 2;
        CLOUD_PROVIDER_AZURE = 3;
    }
}

syntax = "proto3";

package temporal.api.cloud.operation.v1;

option go_package = "go.temporal.io/api/cloud/operation/v1;operation";
option java_package = "io.temporal.api.cloud.operation.v1";
option java_multiple_files = true;
option java_outer_classname = "MessageProto";
option ruby_package = "Temporalio::Api::Cloud::Operation::V1";
option csharp_namespace = "Temporalio.Api.Cloud.Operation.V1";

import "google/protobuf/duration.proto";
import "google/protobuf/timestamp.proto";
import "google/protobuf/any.proto";

message AsyncOperation {
    // The operation id.
    string id = 1;
    // The current state of this operation.
    // Possible values are: pending, in_progress, failed, cancelled, fulfilled.
    // Deprecated: Not supported after v0.3.0 api version. Use state instead.
    // temporal:versioning:max_version=v0.3.0
    string state_deprecated = 2 [deprecated = true];
    // The current state of this operation.
    // temporal:versioning:min_version=v0.3.0
    // temporal:enums:replaces=state_deprecated
    State state = 9;
    // The recommended duration to check back for an update in the operation's state.
    google.protobuf.Duration check_duration = 3;
    // The type of operation being performed.
    string operation_type = 4;
    // The input to the operation being performed.
    //
    // (-- api-linter: core::0146::any=disabled --)
    google.protobuf.Any operation_input = 5;
    // If the operation failed, the reason for the failure.
    string failure_reason = 6;
    // The date and time when the operation initiated.
    google.protobuf.Timestamp started_time = 7;
    // The date and time when the operation completed.
    google.protobuf.Timestamp finished_time = 8;

    enum State {
        STATE_UNSPECIFIED = 0;
        STATE_PENDING = 1;     // The operation is pending.
        STATE_IN_PROGRESS = 2; // The operation is in progress.
        STATE_FAILED = 3;      // The operation failed, check failure_reason for more details.
        STATE_CANCELLED = 4;   // The operation was cancelled.
        STATE_FULFILLED = 5;   // The operation was fulfilled.
        STATE_REJECTED = 6;    // The operation was rejected.
    }
}

