package temporal.api.cloud.resource.v1;

option go_package = "go.temporal.io/api/cloud/resource/v1;resource";
option java_package = "io.temporal.api.cloud.resource.v1";
option java_multiple_files = true;
option java_outer_classname = "MessageProto";
option ruby_package = "Temporalio::Api::Cloud::Resource::V1";
option csharp_namespace = "Temporalio.Api.Cloud.Resource.V1";


enum ResourceState {
    RESOURCE_STATE_UNSPECIFIED = 0;
    RESOURCE_STATE_ACTIVATING = 1;         // The resource is being activated.
    RESOURCE_STATE_ACTIVATION_FAILED = 2;  // The resource failed to activate. This is an error state. Reach out to support for remediation.
    RESOURCE_STATE_ACTIVE = 3;             // The resource is active and ready to use.
    RESOURCE_STATE_UPDATING = 4;           // The resource is being updated.
    RESOURCE_STATE_UPDATE_FAILED = 5;      // The resource failed to update. This is an error state. Reach out to support for remediation.
    RESOURCE_STATE_DELETING = 6;           // The resource is being deleted.
    RESOURCE_STATE_DELETE_FAILED = 7;      // The resource failed to delete. This is an error state. Reach out to support for remediation.
    RESOURCE_STATE_DELETED = 8;            // The resource has been deleted.
    RESOURCE_STATE_SUSPENDED = 9;          // The resource is suspended and not available for use. Reach out to support for remediation.
    RESOURCE_STATE_EXPIRED = 10;           // The resource has expired and is no longer available for use.
}

syntax = "proto3";

package temporal.api.cloud.nexus.v1;

option go_package = "go.temporal.io/api/cloud/nexus/v1;nexus";
option java_package = "io.temporal.api.cloud.nexus.v1";
option java_multiple_files = true;
option java_outer_classname = "MessageProto";
option ruby_package = "Temporalio::Api::Cloud::Nexus::V1";
option csharp_namespace = "Temporalio.Api.Cloud.Nexus.V1";

import "temporal/api/common/v1/message.proto";
import "temporal/api/cloud/resource/v1/message.proto";
import "google/protobuf/timestamp.proto";

message EndpointSpec {
    // The name of the endpoint. Must be unique within an account.
    // The name must match `^[a-zA-Z][a-zA-Z0-9\-]*[a-zA-Z0-9]$`.
    // This field is mutable.
    string name = 1;

    // Indicates where the endpoint should forward received nexus requests to. 
    EndpointTargetSpec target_spec = 2;

    // The set of policies (e.g. authorization) for the endpoint. Each request's caller
    // must match with at least one of the specs to be accepted by the endpoint.
    // This field is mutable.
    repeated EndpointPolicySpec policy_specs = 3;

    // Deprecated: Not supported after v0.4.0 api version. Use description instead.
    // temporal:versioning:max_version=v0.4.0
    string description_deprecated = 4 [deprecated = true];

    // The markdown description of the endpoint - optional.
    // temporal:versioning:min_version=v0.4.0
    temporal.api.common.v1.Payload description = 5;
}

message EndpointTargetSpec {
    oneof variant {
        // A target spec for routing nexus requests to a specific cloud namespace worker.
        WorkerTargetSpec worker_target_spec = 1;
    }
}

message WorkerTargetSpec {
    // The target cloud namespace to route requests to. Namespace must be in same account as the endpoint. This field is mutable.
    string namespace_id = 1;

    // The task queue on the cloud namespace to route requests to. This field is mutable.
    string task_queue = 2;
}

message EndpointPolicySpec {
    oneof variant {
        // A policy spec that allows one caller namespace to access the endpoint.
        AllowedCloudNamespacePolicySpec allowed_cloud_namespace_policy_spec = 1;
    }
}

message AllowedCloudNamespacePolicySpec {
    // The namespace that is allowed to call into this endpoint. Calling namespace must be in same account as the endpoint.
    string namespace_id = 1;
}

// An endpoint that receives and then routes Nexus requests
message Endpoint {
    // The id of the endpoint. This is generated by the server and is immutable.
    string id = 1;

    // The current version of the endpoint specification.
    // The next update operation must include this version.
    string resource_version = 2;

    // The endpoint specification.
    EndpointSpec spec = 3;

    // The current state of the endpoint.
    // For any failed state, reach out to Temporal Cloud support for remediation.
    temporal.api.cloud.resource.v1.ResourceState state = 4;

    // The id of any ongoing async operation that is creating, updating, or deleting the endpoint, if any.
    string async_operation_id = 5;

    // The date and time when the endpoint was created.
    google.protobuf.Timestamp created_time = 6;

    // The date and time when the endpoint was last modified.
    google.protobuf.Timestamp last_modified_time = 7;

    // The id of the project this endpoint belongs to.
    string project_id = 8;
}

syntax = "proto3";

package temporal.api.cloud.connectivityrule.v1;

option go_package = "go.temporal.io/api/cloud/connectivityrule/v1;connectivityrule";
option java_package = "io.temporal.api.cloud.connectivityrule.v1";
option java_multiple_files = true;
option java_outer_classname = "MessageProto";
option ruby_package = "Temporalio::Api::Cloud::ConnectivityRule::V1";
option csharp_namespace = "Temporalio.Api.Cloud.ConnectivityRule.V1";

import "temporal/api/cloud/resource/v1/message.proto";
import "google/protobuf/timestamp.proto";

message ConnectivityRule {
  reserved 3; // Removed endpoint field

  // The id of the private connectivity rule.
  string id = 1;

  // The connectivity rule specification.
  ConnectivityRuleSpec spec = 2;

  // The current version of the connectivity rule specification.
  // The next update operation will have to include this version.
  string resource_version = 4;

  temporal.api.cloud.resource.v1.ResourceState state = 5;

  // The id of the async operation that is creating/updating/deleting the connectivity rule, if any.
  string async_operation_id = 6;

  // The date and time when the connectivity rule was created.
  google.protobuf.Timestamp created_time = 7;

  // The ID of the project this connectivity rule belongs to.
  string project_id = 8;
}

// The connectivity rule specification passed in on create/update operations.
message ConnectivityRuleSpec {
  oneof connection_type {
    // This allows access via public internet.
    PublicConnectivityRule public_rule = 1;
    // This allows access via specific private vpc.
    PrivateConnectivityRule private_rule = 2;
  }
}

// A public connectivity rule allows access to the namespace via the public internet.
message PublicConnectivityRule {
  // Flag to determine namespace is connected via a predictable set of IPs on public internet
  // temporal:versioning:min_version=v0.15.0
  bool enable_stable_ips = 1;
}

// A private connectivity rule allows connections from a specific private vpc only.
message PrivateConnectivityRule {
  // Connection id provided by user to enforce the private connectivity.
  // For AWS: VPC endpoint ID (e.g. "vpce-0123456789abcdef0").
  // For GCP: PSC connection ID (numeric string).
  // For Azure: not set by the customer; populated internally with the PPv2 LinkID
  // returned by the infra plane during Private Endpoint connection approval.
  string connection_id = 1;

  // For GCP private connectivity service, GCP needs both GCP project id and the Private Service Connect Connection IDs.
  // AWS only needs the connection_id.
  string gcp_project_id = 2;

  // The region of the connectivity rule. This should align with the namespace.
  // Example: "aws-us-west-2", "gcp-us-central1", "azure-eastus"
  string region = 3;

  reserved 4;

  // azure_pe_resource_id is the ARM resource ID of the customer's Azure Private Endpoint.
  // Required for Azure private connectivity rules.
  // Example: "/subscriptions/{sub}/resourceGroups/{rg}/providers/Microsoft.Network/privateEndpoints/{name}"
  // temporal:versioning:min_version=v0.18.0
  string azure_pe_resource_id = 5;
}

syntax = "proto3";

package temporal.api.cloud.sink.v1;

option go_package = "go.temporal.io/api/cloud/sink/v1;sink";
option java_package = "io.temporal.api.cloud.sink.v1";
option java_multiple_files = true;
option java_outer_classname = "MessageProto";
option ruby_package = "Temporalio::Api::Cloud::Sink::V1";
option csharp_namespace = "Temporalio.Api.Cloud.Sink.V1";

message S3Spec {
    // The IAM role that Temporal Cloud assumes for writing records to the customer's S3 bucket.
    string role_name = 1;

    // The name of the destination S3 bucket where Temporal will send data.
    string bucket_name = 2;

    // The region where the S3 bucket is located.
    string region = 3;

    // The AWS Key Management Service (KMS) ARN used for encryption.
    string kms_arn = 4;

    // The AWS account ID associated with the S3 bucket and the assumed role.
    string aws_account_id = 5;
}

message GCSSpec {
    // The customer service account ID that Temporal Cloud impersonates for writing records to the customer's GCS bucket.
    string sa_id = 1;

    // The name of the destination GCS bucket where Temporal will send data.
    string bucket_name = 2;

    // The GCP project ID associated with the GCS bucket and service account.
    string gcp_project_id = 3;

    // The region of the gcs bucket
    string region = 4;
}

message AzureBlobSpec {
    // The customer's Azure tenant ID where the storage account exists and where Temporal's app registration is consented/granted access.
    string tenant_id = 1;

    // The name of the destination Azure storage account where Temporal will send data.
    string storage_account = 2;

    // The name of the destination Azure Blob container where Temporal will send data.
    string container_name = 3;

    // The region where the Azure storage account is located.
    string region = 4;

    // The Azure subscription ID that contains the storage account.
    string subscription_id = 5;

    // The Azure resource group that contains the storage account.
    string resource_group = 6;
}

message KinesisSpec {
    // The role Temporal Cloud assumes when writing records to Kinesis
    string role_name = 1;

    // Destination Kinesis endpoint arn for temporal to send data to.
    string destination_uri = 2;

    // The sink's region.
    string region = 3;
}

message PubSubSpec{
    // The customer service account id that Temporal Cloud impersonates for writing records to customer's pubsub topic
    string service_account_id = 1;

    // Destination pubsub topic name for us
    string topic_name = 2;

    // The gcp project id of pubsub topic and service account
    string gcp_project_id = 3;
}

syntax = "proto3";

package temporal.api.cloud.account.v1;

option go_package = "go.temporal.io/api/cloud/account/v1;account";
option java_package = "io.temporal.api.cloud.account.v1";
option java_multiple_files = true;
option java_outer_classname = "MessageProto";
option ruby_package = "Temporalio::Api::Cloud::Account::V1";
option csharp_namespace = "Temporalio.Api.Cloud.Account.V1";

import "temporal/api/cloud/resource/v1/message.proto";
import "temporal/api/cloud/sink/v1/message.proto";
import "google/protobuf/timestamp.proto";

message MetricsSpec {
    // The ca cert(s) in PEM format that clients connecting to the metrics endpoint can use for authentication.
    // This must only be one value, but the CA can have a chain.
    bytes accepted_client_ca = 2;
}

message AuthenticationSettings {
    // Restricts Cloud web UI session lifetimes for users in this account.
    bool restrict_session_lifetimes = 1;
}

message AccountSpec {
    // The metrics specification for this account.
    // If not specified, metrics will not be enabled.
    MetricsSpec metrics = 1;
    // Authentication settings for this account.
    // temporal:versioning:min_version=v0.20.0
    AuthenticationSettings authentication_settings = 2;
}

message Metrics {
    // The prometheus metrics endpoint uri.
    // This is only populated when the metrics is enabled in the metrics specification.
    string uri = 1;
}

message Account {
    // The id of the account.
    string id = 1;
    // The account specification.
    AccountSpec spec = 2;
    // The current version of the account specification.
    // The next update operation will have to include this version.
    string resource_version = 3;
    // The current state of the account.
    temporal.api.cloud.resource.v1.ResourceState state = 4;
    // The id of the async operation that is updating the account, if any.
    string async_operation_id = 5;
    // Information related to metrics.
    Metrics metrics = 6;
}

// AuditLogSinkSpec is only used by Audit Log
message AuditLogSinkSpec {
  // Name of the sink e.g. "audit_log_01"
  string name = 1;

  oneof sink_type {
    // The KinesisSpec when destination_type is Kinesis
    api.cloud.sink.v1.KinesisSpec kinesis_sink = 2;

    // The PubSubSpec when destination_type is PubSub
    api.cloud.sink.v1.PubSubSpec pub_sub_sink = 3;
  }

  // Enabled indicates whether the sink is enabled or not.
  bool enabled = 4;
}

// AuditLogSink is only used by Audit Log
message AuditLogSink {
    // Name of the sink e.g. "audit_log_01"
    string name = 1;

    // The version of the audit log sink resource.
    string resource_version = 2;

    // The current state of the audit log sink.
    temporal.api.cloud.resource.v1.ResourceState state = 3;

    // The specification details of the audit log sink.
    AuditLogSinkSpec spec = 4;

    // The health status of the audit log sink.
    Health health = 5;

    // An error message describing any issues with the audit log sink, if applicable.
    string error_message = 6;

    // The last succeeded timestamp for the internal workflow responsible for adding data to the sink.
    google.protobuf.Timestamp last_succeeded_time = 7;

    // The health status of the audit log sink.
    enum Health {
        HEALTH_UNSPECIFIED = 0;
        // The audit log sink is healthy and functioning correctly.
        HEALTH_OK = 1;
        // The audit log sink has an internal error.
        HEALTH_ERROR_INTERNAL = 2;
        // The audit log sink has a configuration error.
        HEALTH_ERROR_USER_CONFIGURATION = 3;
    }
}

syntax = "proto3";

package temporal.api.cloud.identity.v1;

option go_package = "go.temporal.io/api/cloud/identity/v1;identity";
option java_package = "io.temporal.api.cloud.identity.v1";
option java_multiple_files = true;
option java_outer_classname = "MessageProto";
option ruby_package = "Temporalio::Api::Cloud::Identity::V1";
option csharp_namespace = "Temporalio.Api.Cloud.Identity.V1";

import "temporal/api/cloud/resource/v1/message.proto";
import "google/protobuf/timestamp.proto";

message AccountAccess {
    // The role on the account, should be one of [owner, admin, developer, financeadmin, read, metricsread]
    // owner - gives full access to the account, including users, namespaces, and billing
    // admin - gives full access the account, including users and namespaces
    // developer - gives access to create namespaces on the account
    // financeadmin - gives read only access and write access for billing
    // read - gives read only access to the account
    // metricsread - gives read only access to all namespace metrics
    // Deprecated: Not supported after v0.3.0 api version. Use role instead.
    // temporal:versioning:max_version=v0.3.0
    string role_deprecated = 1 [deprecated = true];
    // The role on the account.
    // temporal:versioning:min_version=v0.3.0
    // temporal:enums:replaces=role_deprecated
    Role role = 2;

    enum Role {
        ROLE_UNSPECIFIED = 0;
        ROLE_OWNER = 1; // Gives full access to the account, including users, namespaces, and billing.
        ROLE_ADMIN = 2; // Gives full access to the account, including users and namespaces.
        ROLE_DEVELOPER = 3; // Gives access to create namespaces on the account.
        ROLE_FINANCE_ADMIN = 4; // Gives read only access and write access for billing.
        ROLE_READ = 5; // Gives read only access to the account.
        ROLE_METRICS_READ = 6; // Gives read only access to the account metrics.
    }

    // List of custom role IDs assigned to the user or service account.
    // temporal:versioning:min_version=v0.13.0
    repeated string custom_roles = 3;
}

message NamespaceAccess {
    // The permission to the namespace, should be one of [admin, write, read]
    // admin - gives full access to the namespace, including assigning namespace access to other users
    // write - gives write access to the namespace configuration and workflows within the namespace
    // read - gives read only access to the namespace configuration and workflows within the namespace
    // Deprecated: Not supported after v0.3.0 api version. Use permission instead.
    // temporal:versioning:max_version=v0.3.0
